begin;
create table if not exists public.ac_whatsapp_contact_identities(id uuid primary key default gen_random_uuid(),contact_id uuid,account_id uuid,identity_type text not null check(identity_type in('e164','c_us','lid','remote_chat','push_name','business_name','legacy_alias')),identity_value text not null,canonical_e164 text,is_primary boolean not null default false,confidence smallint not null default 50 check(confidence between 0 and 100),source text not null default 'mz7',first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),verified_at timestamptz,metadata jsonb not null default '{}'::jsonb);
create unique index if not exists ac_whatsapp_contact_identities_unique on public.ac_whatsapp_contact_identities(coalesce(account_id,'00000000-0000-0000-0000-000000000000'::uuid),identity_type,identity_value);
create index if not exists ac_whatsapp_contact_identities_contact_idx on public.ac_whatsapp_contact_identities(contact_id);
create table if not exists public.ac_whatsapp_integrity_audit(id uuid primary key default gen_random_uuid(),audit_type text not null,entity_type text not null,entity_id text,severity text not null default 'info',classification text not null,details jsonb not null default '{}'::jsonb,repaired boolean not null default false,repaired_at timestamptz,created_at timestamptz not null default now());
alter table public.ac_whatsapp_contact_identities enable row level security; alter table public.ac_whatsapp_integrity_audit enable row level security;
do $$ begin if to_regclass('public.ac_whatsapp_attachments') is not null then execute 'alter table public.ac_whatsapp_attachments add column if not exists storage_backend text'; execute 'alter table public.ac_whatsapp_attachments add column if not exists storage_key text'; execute 'alter table public.ac_whatsapp_attachments add column if not exists sha256 text'; execute 'alter table public.ac_whatsapp_attachments add column if not exists transport_message_id text'; execute 'alter table public.ac_whatsapp_attachments add column if not exists transport_status text'; execute 'alter table public.ac_whatsapp_attachments add column if not exists media_status text'; execute 'alter table public.ac_whatsapp_attachments add column if not exists last_verified_at timestamptz'; execute 'create index if not exists ac_whatsapp_attachments_message_integrity_idx on public.ac_whatsapp_attachments(message_id)'; end if; end $$;
create or replace function public.ac_whatsapp_mz7_preserve_contact_identity() returns trigger language plpgsql as $$ declare oldj jsonb:=to_jsonb(old);newj jsonb:=to_jsonb(new);old_name text;new_name text;old_phone text;new_phone text;remote_id text;lid_digits text; begin old_name:=coalesce(oldj->>'display_name',oldj->>'name',oldj->>'contact_name');new_name:=coalesce(newj->>'display_name',newj->>'name',newj->>'contact_name'); if old_name is not null and length(btrim(old_name))>1 and lower(btrim(old_name)) not in('unknown','[unknown]','inconnu','[inconnu]','contact','whatsapp') and(new_name is null or length(btrim(new_name))<2 or lower(btrim(new_name)) in('unknown','[unknown]','inconnu','[inconnu]','contact','whatsapp') or regexp_replace(new_name,'[^0-9+]','','g')~'^\+?[0-9]{7,}$') then if newj?'display_name' then newj:=jsonb_set(newj,'{display_name}',to_jsonb(old_name));end if;if newj?'name' and oldj?'name' then newj:=jsonb_set(newj,'{name}',oldj->'name');end if;if newj?'contact_name' and oldj?'contact_name' then newj:=jsonb_set(newj,'{contact_name}',oldj->'contact_name');end if;end if; old_phone:=coalesce(oldj->>'phone_e164',oldj->>'e164',oldj->>'phone');new_phone:=coalesce(newj->>'phone_e164',newj->>'e164',newj->>'phone');remote_id:=coalesce(newj->>'remote_chat_id',newj->>'whatsapp_id',newj->>'remote_id','');if remote_id~*'@lid$' then lid_digits:=regexp_replace(remote_id,'@lid$','','i');else lid_digits:=null;end if;if old_phone~'^\+[1-9][0-9]{7,14}$' and(new_phone is null or new_phone='' or new_phone!~'^\+[1-9][0-9]{7,14}$' or(lid_digits is not null and regexp_replace(coalesce(new_phone,''),'[^0-9]','','g')=regexp_replace(lid_digits,'[^0-9]','','g'))) then if newj?'phone_e164' then newj:=jsonb_set(newj,'{phone_e164}',to_jsonb(old_phone));end if;if newj?'e164' and oldj?'e164' then newj:=jsonb_set(newj,'{e164}',oldj->'e164');end if;if newj?'phone' and oldj?'phone' then newj:=jsonb_set(newj,'{phone}',oldj->'phone');end if;end if;new:=jsonb_populate_record(new,newj);return new;end;$$;
do $$ begin if to_regclass('public.ac_whatsapp_contacts') is not null then execute 'drop trigger if exists ac_whatsapp_mz7_preserve_contact_identity_trg on public.ac_whatsapp_contacts';execute 'create trigger ac_whatsapp_mz7_preserve_contact_identity_trg before update on public.ac_whatsapp_contacts for each row execute function public.ac_whatsapp_mz7_preserve_contact_identity()';end if;end $$;
commit;
